"""
Writes the TRADE-ANALYSIS-<TICKER>.md report in the exact format
specified by the trade-analyze prompt.

Pure I/O — receives pre-computed dicts from ai_orchestrator and writes the
markdown. No network calls, no Kite dependency.
"""

import datetime
import os


DISCLAIMER = (
    "\n\n---\n\n"
    "> **DISCLAIMER:** This analysis is generated by an AI system for educational "
    "and research purposes only. It is NOT financial advice. It does NOT constitute "
    "a recommendation to buy, sell, or hold any security. Past performance does not "
    "indicate future results. Always conduct your own due diligence and consult a "
    "licensed financial advisor before making investment decisions. AI-generated "
    "analysis may contain errors or outdated information. Verify all data independently."
)


def write_trade_analysis_report(
    ticker: str,
    company_name: str,
    agent_results: dict,
    trade_score_result: dict,
    discovery_brief: dict,
    output_dir: str = "reports",
) -> str:
    """
    agent_results keys: "technical", "fundamental", "sentiment", "risk", "thesis"
    Each value is the raw text returned by that agent.

    trade_score_result: output of trade_score.calculate_composite_score()
    discovery_brief: the Phase 1 data dict

    Returns the absolute path to the written file.
    """
    os.makedirs(output_dir, exist_ok=True)
    filename = f"TRADE-ANALYSIS-{ticker.upper()}.md"
    filepath = os.path.join(output_dir, filename)

    today_str = datetime.date.today().strftime("%d %B %Y")
    score = trade_score_result["score"]
    grade = trade_score_result["grade"]
    signal = trade_score_result["signal"]
    bd = trade_score_result["breakdown"]

    # ---------------------------------------------------------------- helpers
    def _w(dim):
        return bd[dim]["weighted"]

    def _s(dim):
        return bd[dim]["score"]

    # ---------------------------------------------------------------- header
    lines = [
        f"# Trade Analysis: {ticker.upper()} — {company_name}",
        f"> Generated by StockEdge Options — AI Trading Analyst | {today_str}",
        "",
        "---",
        "",
        "## Executive Summary",
        "",
    ]

    # Executive summary from discovery brief + overall score
    exec_summary = discovery_brief.get("executive_summary", "")
    if not exec_summary:
        price = discovery_brief.get("current_price", "N/A")
        sector = discovery_brief.get("sector", "N/A")
        exec_summary = (
            f"{company_name} ({ticker.upper()}) is a NSE-listed F&O stock in the "
            f"{sector} sector, currently trading at ₹{price}. "
            f"The comprehensive AI analysis across 5 dimensions yields a Composite "
            f"Trade Score of **{score}/100** (Grade: **{grade}** — {signal}). "
            f"Review the detailed sections below before making any trading decision."
        )
    lines.append(exec_summary)
    lines.append("")
    lines.append("---")
    lines.append("")

    # ---------------------------------------------------------------- score dashboard
    lines += [
        "## Trade Score Dashboard",
        "",
        "| Dimension | Score | Weight | Weighted |",
        "|-----------|-------|--------|----------|",
        f"| Technical Strength    | {_s('technical')}/100   | 25% | {_w('technical'):.1f} |",
        f"| Fundamental Quality   | {_s('fundamental')}/100 | 25% | {_w('fundamental'):.1f} |",
        f"| Sentiment & Momentum  | {_s('sentiment')}/100   | 20% | {_w('sentiment'):.1f} |",
        f"| Risk Profile          | {_s('risk')}/100        | 15% | {_w('risk'):.1f} |",
        f"| Thesis Conviction     | {_s('thesis')}/100      | 15% | {_w('thesis'):.1f} |",
        f"| **Composite Trade Score** | | | **{score}/100** |",
        "",
        f"**Grade: {grade}** | **Signal: {signal}**",
        "",
    ]

    # Sub-score breakdown — parsed from agent text
    tech_text = agent_results.get("technical", "")
    fund_text = agent_results.get("fundamental", "")
    sent_text = agent_results.get("sentiment", "")
    risk_text = agent_results.get("risk", "")
    thes_text = agent_results.get("thesis", "")

    lines += [
        "### Sub-Score Breakdown",
        "",
        f"**Technical** [{_s('technical')}/100]: *(see Technical Analysis section)*",
        f"**Fundamental** [{_s('fundamental')}/100]: *(see Fundamental Analysis section)*",
        f"**Sentiment** [{_s('sentiment')}/100]: *(see Sentiment Analysis section)*",
        f"**Risk** [{_s('risk')}/100]: *(see Risk Assessment section)*",
        f"**Thesis** [{_s('thesis')}/100]: *(see Investment Thesis section)*",
        "",
        "---",
        "",
    ]

    # ---------------------------------------------------------------- agent sections
    sections = [
        ("## Technical Analysis",    tech_text),
        ("## Fundamental Analysis",  fund_text),
        ("## Sentiment Analysis",    sent_text),
        ("## Risk Assessment",       risk_text),
        ("## Investment Thesis",     thes_text),
    ]
    for header, content in sections:
        lines.append(header)
        lines.append("")
        lines.append(content.strip() if content else "_Agent data unavailable._")
        lines.append("")
        lines.append("---")
        lines.append("")

    # ---------------------------------------------------------------- entry/exit strategy
    entry_zone = discovery_brief.get("entry_zone", "N/A")
    stop_loss = discovery_brief.get("stop_loss", "N/A")
    target1 = discovery_brief.get("target1", "N/A")
    target2 = discovery_brief.get("target2", "N/A")
    rr_ratio = discovery_brief.get("rr_ratio", "N/A")
    timeframe = discovery_brief.get("timeframe", "Swing / Position trade")

    lines += [
        "## Entry/Exit Strategy",
        "",
        "| Parameter | Level | Notes |",
        "|-----------|-------|-------|",
        f"| Entry Zone  | {entry_zone} | From Technical Agent |",
        f"| Stop Loss   | {stop_loss}  | Mandatory for futures |",
        f"| Target 1    | {target1}    | Conservative upside |",
        f"| Target 2    | {target2}    | Aggressive upside |",
        f"| Risk/Reward | {rr_ratio}   | At midpoint entry to T1 |",
        f"| Timeframe   | {timeframe}  | |",
        "",
        "---",
        "",
    ]

    # ---------------------------------------------------------------- Option Chain (ATM +/- 5 Strikes)
    opt_chain = discovery_brief.get("option_chain")
    if opt_chain and opt_chain.get("rows"):
        atm_val = opt_chain.get("atm_strike", "N/A")
        step_val = opt_chain.get("strike_interval", "N/A")
        exp_val = opt_chain.get("nearest_expiry", "N/A")
        pcr_val = opt_chain.get("pcr")
        pcr_str = f"{pcr_val:.2f}" if isinstance(pcr_val, (int, float)) else "N/A"
        wpcr_val = opt_chain.get("weighted_pcr")
        wpcr_str = f"{wpcr_val:.2f}" if isinstance(wpcr_val, (int, float)) else "N/A"
        oi_bias_str = opt_chain.get("oi_bias", "NEUTRAL")
        res_str = f"₹{opt_chain.get('resistance_strike', 'N/A')} (OI: {opt_chain.get('resistance_oi', 0):,})"
        sup_str = f"₹{opt_chain.get('support_strike', 'N/A')} (OI: {opt_chain.get('support_oi', 0):,})"
        ce_prem = opt_chain.get("ce_premium")
        pe_prem = opt_chain.get("pe_premium")
        net_prem = opt_chain.get("net_premium")
        req_both = opt_chain.get("required_move_both")
        ce_prem_str = f"₹{ce_prem:.2f}" if isinstance(ce_prem, (int, float)) else "N/A"
        pe_prem_str = f"₹{pe_prem:.2f}" if isinstance(pe_prem, (int, float)) else "N/A"
        net_prem_str = f"₹{net_prem:.2f}" if isinstance(net_prem, (int, float)) else "N/A"
        req_both_str = f"±₹{req_both:.1f} pts" if isinstance(req_both, (int, float)) else "N/A"
        up_prob = opt_chain.get("upside_probability", 0.5)
        dn_prob = opt_chain.get("downside_probability", 0.5)

        lines += [
            "## Option Chain Analysis (ATM ± 5 Strikes)",
            f"> Expiry: **{exp_val}** | Strike Step: **₹{step_val}** | ATM Strike: **₹{atm_val}**",
            "",
            "| Derivative Metric | Value | Institutional Interpretation |",
            "|-------------------|-------|------------------------------|",
            f"| **Put-Call Ratio (PCR)** | {pcr_str} (Weighted: {wpcr_str}) | **{oi_bias_str}** |",
            f"| **Resistance Wall (Ceiling)** | {res_str} | Major Call Writing Resistance |",
            f"| **Support Wall (Floor)** | {sup_str} | Major Put Writing Support |",
            f"| **ATM Straddle Premium** | CE: {ce_prem_str} + PE: {pe_prem_str} = **{net_prem_str}** | Net Breakeven Move: {req_both_str} |",
            f"| **Option Direction Odds** | ▲ Upside {up_prob*100:.0f}% vs {dn_prob*100:.0f}% Downside ▼ | Institutional Probability Split |",
            "",
            "### 11-Strike Derivative Chain",
            "| Calls OI | Calls Vol | Calls LTP | Strike | Puts LTP | Puts Vol | Puts OI |",
            "|---------:|----------:|----------:|:------:|---------:|---------:|--------:|",
        ]

        for r in opt_chain["rows"]:
            s = r["strike"]
            strike_label = f"**{s:g} [ATM]**" if r.get("is_atm") else f"{s:g}"
            if r.get("is_resistance"):
                strike_label += " 🔴[RES]"
            if r.get("is_support"):
                strike_label += " 🟢[SUP]"

            c_oi = f"{r['ce']['oi']:,}" if r.get("ce", {}).get("oi") else "0"
            c_vol = f"{r['ce']['volume']:,}" if r.get("ce", {}).get("volume") else "0"
            c_ltp = f"₹{r['ce']['ltp']:.2f}" if r.get("ce", {}).get("ltp") is not None else "—"

            p_oi = f"{r['pe']['oi']:,}" if r.get("pe", {}).get("oi") else "0"
            p_vol = f"{r['pe']['volume']:,}" if r.get("pe", {}).get("volume") else "0"
            p_ltp = f"₹{r['pe']['ltp']:.2f}" if r.get("pe", {}).get("ltp") is not None else "—"

            lines.append(f"| {c_oi} | {c_vol} | {c_ltp} | {strike_label} | {p_ltp} | {p_vol} | {p_oi} |")

        lines += [
            "",
            "---",
            "",
        ]

    # ---------------------------------------------------------------- Chartink ADX Volume Setup
    adx_setup = discovery_brief.get("adx_volume_setup") or discovery_brief.get("live_chartink_adx_setup") or {}
    status_str = adx_setup.get("status", "N/A")
    plus_di_str = str(adx_setup.get("plus_di") or adx_setup.get("values", {}).get("plus_di") or "N/A")
    vol_vs_wma = str(adx_setup.get("volume_vs_10wma") or adx_setup.get("values", {}).get("volume_multiple") or "N/A")
    ema_align = adx_setup.get("ema_alignment") or "5-min Close > EMA 8, 34, 50"
    setup_notes = adx_setup.get("notes") or adx_setup.get("summary") or "High momentum volume & ADX breakout scan."

    lines += [
        "## Intraday Buy Setup (ADX & Volume Filter)",
        "> Reference Screener: [My-intraday-buy-setup-ADX (Chartink)](https://chartink.com/screener/my-intraday-buy-setup-adx)",
        "",
        f"**Setup Status: {status_str}** | **+DI(14): {plus_di_str}** | **Volume Surge: {vol_vs_wma}**",
        "",
        "| Filter Condition | Target Specification | Current Evaluation |",
        "|------------------|----------------------|--------------------|",
        f"| Multiple EMA Alignment | Close > EMA(8), EMA(34), EMA(50) [5-min] | {ema_align} |",
        f"| Volume Expansion | Volume > 10-period WMA of Volume [5-min] | {vol_vs_wma} |",
        f"| Directional Momentum | +DI(14) >= 24 with strong ADX | +DI: {plus_di_str} |",
        f"| Setup Verdict | High momentum confluence | **{status_str}** |",
        "",
        f"> **Filter Notes:** {setup_notes}",
        "",
        "---",
        "",
    ]

    # ---------------------------------------------------------------- bull vs bear
    bull_points = discovery_brief.get("bull_points", ["(from Thesis Agent)", "", "", "", ""])
    bear_points = discovery_brief.get("bear_points", ["(from Thesis Agent)", "", "", "", ""])
    bull_target = discovery_brief.get("bull_target", "N/A")
    bear_target = discovery_brief.get("bear_target", "N/A")

    # Pad to 5
    while len(bull_points) < 5:
        bull_points.append("")
    while len(bear_points) < 5:
        bear_points.append("")

    lines += [
        "## Bull vs Bear",
        "",
        "| Bull Case | Bear Case |",
        "|-----------|-----------|",
    ]
    for b, s in zip(bull_points[:5], bear_points[:5]):
        lines.append(f"| {b} | {s} |")
    lines += [
        f"| **Bull Target: {bull_target}** | **Bear Target: {bear_target}** |",
        "",
        "---",
        "",
    ]

    # ---------------------------------------------------------------- catalyst calendar
    catalysts = discovery_brief.get("catalysts", [])
    lines += [
        "## Catalyst Calendar",
        "",
        "| Date | Event | Expected Impact |",
        "|------|-------|-----------------|",
    ]
    if catalysts:
        for c in catalysts:
            lines.append(f"| {c.get('date','TBD')} | {c.get('event','—')} | {c.get('impact','Neutral')} |")
    else:
        lines.append("| — | No specific catalysts identified | — |")

    lines.append("")
    lines.append(DISCLAIMER)

    content = "\n".join(lines)
    with open(filepath, "w", encoding="utf-8") as f:
        f.write(content)

    return os.path.abspath(filepath)
